select case when quantity >= 246 then 'high' when quantity >= 47 then 'mid' else 'low' end as quantity_bucket, min(last_restock) as first_last_restock, count(quantity) as quantity_count, count(distinct quantity) as unique_products from inventory where product_id in (2, 9) or last_restock > '2024-03-01' group by case when quantity >= 246 then 'high' when quantity >= 47 then 'mid' else 'low' end having count(quantity) >= 4 order by unique_products desc;
